func (a *tslabs) SetBudgetControl(c *rt.BudgetControl) { a.control = c }

func (a *tslabs) spend() {
	if a.control == nil || !a.result {
		return
	}
	a.steps++
	if a.steps%256 == 0 {
		a.control.Check()
	}
}

