// ParseValue parses the input like Parse and returns the result as typed values. If the parse recovered
// from errors, the result is returned together with SyntaxErrors; an Error node where a struct
// type is expected becomes nil.
// It builds the values directly, without the nodes Parse returns.
func ParseValue(input string, opts ...sxirruntime.ParseOption) (*types.File, error) {
	a := &tslabs{}
	return rt.TParse(trules[0], input, opts, a, func(v any) *types.File { a.result = true; return rt.TAs[*types.File](v) })
}

// ParseRuleValue parses the whole input with the named start rule and returns its typed value; an empty
// name selects the grammar's default start rule.
// Recovered values accompany SyntaxErrors. Nil results and failed parses return the selected type's zero value.
// Invalid options and names of rules that are not start rules return nil with an error. Start rule result types:
//
//	main: *types.File
//	file: *types.File
func ParseRuleValue(name, input string, opts ...sxirruntime.ParseOption) (any, error) {
	o, err := rt.ResolveOptions(sxirGrammar, opts)
	if err != nil {
		return nil, err
	}
	switch name {
	case "main", "":
		a := &tslabs{}
		return rt.TParseResolved(trules[0], input, o, a, func(v any) *types.File { a.result = true; return rt.TAs[*types.File](v) })
	case "file":
		a := &tslabs{}
		return rt.TParseResolved(trules[1], input, o, a, func(v any) *types.File { a.result = true; return rt.TAs[*types.File](v) })
	default:
		return nil, sxirGrammar.StartError(name)
	}
}

